def load_projects():
    if "studio_projects" not in st.session_state:
        try:
            with open("afterimage_projects.json", "r", encoding="utf-8") as file:
                data = json.load(file)
            st.session_state.studio_projects = data if isinstance(data, list) else []
        except (FileNotFoundError, json.JSONDecodeError):
            st.session_state.studio_projects = []
    return st.session_state.studio_projects


def save_projects(items):
    st.session_state.studio_projects = items
    with open("afterimage_projects.json", "w", encoding="utf-8") as file:
        json.dump(items, file, ensure_ascii=False, indent=2)


def render_navigation(section):
    """모든 하위 화면에서 공통으로 사용하는 상단 내비게이션."""
    st.markdown("""
    <style>
      .global-nav-wrap{display:flex;align-items:center;justify-content:space-between;
        border-bottom:1px solid #deded8;padding:17px 0 15px;margin-bottom:24px}
      .global-nav-label{font:10px 'DM Sans',sans-serif;letter-spacing:2px;color:#888;text-align:center}
      .global-nav-wrap .stButton>button{min-height:36px!important;padding:0 13px!important;
        background:transparent!important;border:1px solid #deded8!important;
        color:#333!important;font-size:10px!important;letter-spacing:1.5px!important}
      .global-nav-wrap .stButton>button:hover{background:#f2df50!important;border-color:#d6bd24!important}
      .global-nav-wrap div[data-testid="column"]:first-child .stButton>button{
        border:0!important;color:#b49d16!important;font:300 27px 'Barlow Condensed',sans-serif!important;
        letter-spacing:2px!important;text-align:left!important;padding-left:0!important}
    </style>
    """, unsafe_allow_html=True)
    st.markdown('<div class="global-nav-wrap">', unsafe_allow_html=True)
    left, middle, right = st.columns([1.7, 3.3, 1])
    with left:
        st.markdown("<div style=\"font:300 27px 'Barlow Condensed',sans-serif;letter-spacing:2px;color:#b49d16\">AFTERIMAGE.</div>", unsafe_allow_html=True)
    with middle:
        st.markdown(f'<div class="global-nav-label">{html.escape(section.upper())}</div>',
                    unsafe_allow_html=True)
    with right:
        if st.button("← HOME", key="nav_home_" + section, use_container_width=True):
            st.session_state.page = "landing"
            st.rerun()
    st.markdown('</div>', unsafe_allow_html=True)


def page_heading(kicker, title, subtitle):
    st.markdown(
        f'<div style="padding:12px 0 28px">'
        f'<div class="studio-kicker">{html.escape(kicker)}</div>'
        f'<div class="studio-title">{html.escape(title)}</div>'
        f'<div class="studio-sub">{html.escape(subtitle)}</div></div>',
        unsafe_allow_html=True
    )


def load_exhibitions():
    try:
        with open("afterimage_exhibitions.json", "r", encoding="utf-8") as f:
            data = json.load(f)
            return data if isinstance(data, list) else []
    except (FileNotFoundError, json.JSONDecodeError):
        return []


def save_exhibitions(items):
    with open("afterimage_exhibitions.json", "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False, indent=2)


def image_as_data_uri(path):
    if not path or not os.path.exists(path):
        return ""
    ext = os.path.splitext(path)[1].lower()
    mime = "image/png" if ext == ".png" else "image/webp" if ext == ".webp" else "image/jpeg"
    try:
        with open(path, "rb") as f:
            encoded = base64.b64encode(f.read()).decode("ascii")
        return f"data:{mime};base64,{encoded}"
    except OSError:
        return ""


