def new_project_page():
    apply_light_page_style()
    render_navigation("MY STUDIO / NEW PROJECT")
    page_heading("ADD TO YOUR ARCHIVE", "NEW PROJECT",
                 "작품 이미지와 정보를 등록하면 MY STUDIO에 바로 추가됩니다.")

    projects = load_projects()
    with st.form("new_project_form", clear_on_submit=True):
        uploaded_image = st.file_uploader("ARTWORK IMAGE", type=["png", "jpg", "jpeg", "webp"])
        name = st.text_input("PROJECT TITLE", placeholder="작품 제목을 입력하세요")
        category = st.selectbox("CATEGORY", ["ILLUSTRATION", "PHOTOGRAPHY", "GRAPHIC DESIGN", "3D & MOTION"])
        desc = st.text_area("DESCRIPTION", placeholder="작품에 대한 짧은 설명을 입력하세요")
        submitted = st.form_submit_button("＋  ADD TO MY ARCHIVE", use_container_width=True)

        if submitted:
            if not name.strip():
                st.warning("프로젝트 제목을 입력해 주세요.")
            elif uploaded_image is None:
                st.warning("작품 이미지를 업로드해 주세요.")
            else:
                os.makedirs("uploaded_projects", exist_ok=True)
                safe_name = re.sub(r"[^a-zA-Z0-9가-힣_-]", "_", name.strip())[:40]
                ext = os.path.splitext(uploaded_image.name)[1].lower() or ".png"
                image_path = os.path.join("uploaded_projects", safe_name + "_" + str(len(projects) + 1) + ext)
                with open(image_path, "wb") as image_file:
                    image_file.write(uploaded_image.getbuffer())

                new_item = {
                    "id": str(len(projects) + 1) + "_" + safe_name,
                    "name": name.strip(),
                    "category": category,
                    "desc": desc.strip() or "설명이 등록되지 않았습니다.",
                    "date": "ADDED TODAY",
                    "image_path": image_path
                }
                projects.insert(0, new_item)
                save_projects(projects)
                st.session_state.studio_category = "ALL PROJECTS"
                st.session_state.page = "studio"
                st.rerun()

    if st.button("← BACK TO MY STUDIO"):
        st.session_state.page = "studio"
        st.rerun()


def project_detail_page():
    apply_light_page_style()
    detail_theme = THEMES.get(st.session_state.get("selected_exhibition_theme", "WHITE SPACE"), THEMES["WHITE SPACE"])
    st.markdown(f"""<style>
      html, body, [data-testid=\"stAppViewContainer\"], .block-container {{background:{detail_theme['bg']} !important;color:{detail_theme['fg']} !important;}}
      [data-testid=\"stHeader\"] {{background:{detail_theme['bg']} !important;}}
      .block-container {{padding:2rem 4vw 3rem !important;}}
      .stMarkdown, .stMarkdown p, .stCaption {{color:{detail_theme['fg']} !important;}}
      .stButton>button {{border-color:{detail_theme['accent']} !important;color:{detail_theme['fg']} !important;}}
    </style>""", unsafe_allow_html=True)
    render_navigation("PROJECT ARCHIVE / DETAIL")
    projects = load_projects()
    selected_id = st.session_state.get("selected_project_id")
    selected_name = st.session_state.get("selected_project", "")
    project = next((p for p in projects if selected_id and str(p.get("id", "")) == str(selected_id)), None)
    if project is None:
        snapshot = st.session_state.get("selected_project_snapshot")
        if snapshot and str(snapshot.get("id", "")) == str(selected_id or ""):
            project = snapshot
    if project is None:
        project = next((p for p in projects if p.get("name") == selected_name), None)

    if not project:
        st.warning("작품 정보를 찾을 수 없습니다.")
        if st.button("← BACK"):
            st.session_state.page = st.session_state.get("project_detail_return", "studio")
            st.rerun()
        return

    page_heading("PROJECT ARCHIVE", project.get("name", "PROJECT"),
                 project.get("category", "ARTWORK"))
    left, right = st.columns([1.45, 1])
    with left:
        path = project.get("image_path", "")
        if path and os.path.exists(path):
            st.image(path, use_container_width=True)
        elif project.get("image_data"):
            st.markdown(f'<img src="{project["image_data"]}" style="width:100%;height:auto">', unsafe_allow_html=True)
        else:
            st.info("작품 이미지를 찾을 수 없습니다.")
    with right:
        st.markdown('<div style="font:10px DM Sans,sans-serif;letter-spacing:2px;color:#a18c17">ABOUT THE WORK</div>', unsafe_allow_html=True)
        st.markdown(f'<div style="font:25px Georgia,serif;margin:12px 0;color:#222">{html.escape(project.get("name",""))}</div>', unsafe_allow_html=True)
        st.write(project.get("desc", "설명이 등록되지 않았습니다."))
        st.caption("CATEGORY　" + project.get("category", ""))
        st.caption("DATE　" + project.get("date", ""))

    if st.button("← BACK TO EXHIBITION" if st.session_state.get("project_detail_return") in ("exhibition_view", "exhibition_preview") else "← BACK", use_container_width=False):
        st.session_state.page = st.session_state.get("project_detail_return", "studio")
        st.rerun()


